      flavor_ru: "Инфернальный Вознесённый был придворным, принявшим порчу Агграила за лестницу к величию.\nЕго тело уже переросло человеческий облик, и он пожертвует всем оставшимся, чтобы подняться ещё выше.",
      id: 'h_d_3',
