      flavor_ru: "Алебастровая Горгулья выводит бледную ноту, укрепляющую Хор, хотя за каменными губами нет дыхания.\nКогда-то двор ценил её как украшение; теперь она хранит лишь тех, кто полезен Агграилу.",
